53	const ITEM_BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	};
58	const FIRST_INSURANCE_RATE = 0.1;
59	const PROCESSING_FEE = 5;
60	
61	export const runScenario = (scenario: Scenario): ScenarioResult => {
62	  const quote = scenario.steps[0] as QuoteStep;
63	  const policyBasePremium = quote.items.reduce(
64	    (sum, item) => sum + ITEM_BASE_PREMIUMS[item.type],
65	    0,
66	  );
67	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
68	  return {
69	    results: [
70	      { premium: policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE },
71	    ],
72	  };
73	};
